# naive_assistant.py — answers from a fixed snapshot; no retrieval
KNOWN = {
    "parental_leave_weeks": 8,   # true when "trained" — has since changed
}

def answer(question: str) -> str:
    q = question.lower()
    if "parental" in q:
        weeks = KNOWN["parental_leave_weeks"]
        return f"You get {weeks} weeks of parental leave."
    if "wellness" in q:
        # not in KNOWN at all — answers confidently anyway
        return "You get 12 wellness days a year, plus a $500 stipend."
    return "I don't know."
